  // furthest-reaching path at the overlap. Since edit cost to the end never
  // increases along a diagonal, an optimal path passes through this point.
  // Requires both ranges nonempty with differing first and last lines.
  function split(aLo, aHi, bLo, bHi) {
    const N = aHi - aLo;
    const M = bHi - bLo;
    const delta = N - M;
    const odd = (delta & 1) !== 0;
    const dMax = Math.ceil((N + M) / 2);
    const off = dMax + 1;
    vf[off + 1] = 0;
    vb[off + 1] = 0;
    for (let d = 0; d <= dMax; d++) {
      for (let k = -d; k <= d; k += 2) {
        let x = k === -d || (k !== d && vf[off + k - 1] < vf[off + k + 1])
          ? vf[off + k + 1]
          : vf[off + k - 1] + 1;
        let y = x - k;
        while (x < N && y < M && A[aLo + x] === B[bLo + y]) {
          x++;
          y++;
        }
        vf[off + k] = x;
        const kb = delta - k;
        if (odd && kb >= -(d - 1) && kb <= d - 1 && x + vb[off + kb] >= N) {
          return [x, y];
        }
      }
      for (let kb = -d; kb <= d; kb += 2) {
        let x = kb === -d || (kb !== d && vb[off + kb - 1] < vb[off + kb + 1])
          ? vb[off + kb + 1]
          : vb[off + kb - 1] + 1;
        let y = x - kb;
        while (x < N && y < M && A[aHi - 1 - x] === B[bHi - 1 - y]) {
          x++;
          y++;
        }
        vb[off + kb] = x;
        const k = delta - kb;
        if (!odd && k >= -d && k <= d && vf[off + k] + x >= N) {
