'use strict';

const EQUAL = 0;
const DELETE = 1;
const INSERT = 2;
const OP_NAMES = ['equal', 'delete', 'insert'];

/**
 * Map lines to integer ids so the inner loops compare numbers. A Map keeps
 * arbitrary strings (including '__proto__') safe.
 */
function internLines(a, b) {
  const ids = new Map();
  const intern = (lines) => {
    const out = new Int32Array(lines.length);
    for (let i = 0; i < lines.length; i++) {
      let id = ids.get(lines[i]);
      if (id === undefined) {
        id = ids.size;
        ids.set(lines[i], id);
      }
      out[i] = id;
    }
    return out;
  };
  return [intern(a), intern(b)];
}

/**
 * Linear-space Myers diff (divide and conquer on the middle snake).
 * Emits ops as parallel arrays of (code, index into a or b), in order.
 */
function myersOps(A, B) {
  const codes = [];
  const indices = [];
  const max = Math.ceil((A.length + B.length) / 2);
  const vf = new Int32Array(2 * max + 3);
  const vb = new Int32Array(2 * max + 3);

  const emit = (code, index) => {
    codes.push(code);
    indices.push(index);
  };

  // Returns the forward endpoint (x, y), relative to (aLo, bLo), of a
  // furthest-reaching path at the overlap. Since edit cost to the end never
  // increases along a diagonal, an optimal path passes through this point.
  // Requires both ranges nonempty with differing first and last lines.
  function split(aLo, aHi, bLo, bHi) {
    const N = aHi - aLo;
    const M = bHi - bLo;
    const delta = N - M;
    const odd = (delta & 1) !== 0;
    const dMax = Math.ceil((N + M) / 2);
    const off = dMax + 1;
    vf[off + 1] = 0;
    vb[off + 1] = 0;
    for (let d = 0; d <= dMax; d++) {
      for (let k = -d; k <= d; k += 2) {
        let x = k === -d || (k !== d && vf[off + k - 1] < vf[off + k + 1])
          ? vf[off + k + 1]
          : vf[off + k - 1] + 1;
        let y = x - k;
        while (x < N && y < M && A[aLo + x] === B[bLo + y]) {
          x++;
          y++;
        }
        vf[off + k] = x;
        const kb = delta - k;
        if (odd && kb >= -(d - 1) && kb <= d - 1 && x + vb[off + kb] >= N) {
          return [x, y];
        }
      }
      for (let kb = -d; kb <= d; kb += 2) {
        let x = kb === -d || (kb !== d && vb[off + kb - 1] < vb[off + kb + 1])
          ? vb[off + kb + 1]
          : vb[off + kb - 1] + 1;
        let y = x - kb;
        while (x < N && y < M && A[aHi - 1 - x] === B[bHi - 1 - y]) {
          x++;
          y++;
        }
        vb[off + kb] = x;
        const k = delta - kb;
        if (!odd && k >= -d && k <= d && vf[off + k] + x >= N) {
          const fx = vf[off + k];
          return [fx, fx - k];
        }
      }
    }
    throw new Error('diff invariant violated: no middle snake');
  }

